@@ -0,0 +1,24 @@
+import {
+	SubworkflowOperationError,
+	WorkflowActivationError,
+	WorkflowOperationError,
+} from '../../src/errors';
+import { ExpressionError } from '../../src/errors/expression.error';
+
+describe('errors with frozen Error.prototype', () => {
+	beforeAll(() => {
+		Object.freeze(Error.prototype);
+	});
+
+	it('constructs execution errors and sets name', () => {
+		expect(new WorkflowOperationError('msg').name).toBe('WorkflowOperationError');
+		expect(new SubworkflowOperationError('msg', 'desc').name).toBe('SubworkflowOperationError');
+		expect(new ExpressionError('msg').name).toBe('ExpressionError');
+	});
+
+	it('constructs activation errors wrapping an execution error', () => {
+		const cause = new WorkflowOperationError('inner');
+		const error = new WorkflowActivationError('outer', { cause });
+		expect(error.name).toBe('WorkflowActivationError');
+	});
+});
